impl<ServerT> QueuedOperation for QueuedGraphOperation<ServerT>
where
    ServerT: ServerType + 'static,
{
    async fn perform(&self) {
        let resp_processor = GraphResponseProcessor::new();

        let res = self
            .op_sender
            .send_request(
                &self.operation_id,
                &self.name(),
                &self.request,
                &self.options,
                resp_processor,
            )
            .await;

        self.send_result(res);
    }
